            if (databaseAttempted) {
                // A lost commit acknowledgement must never delete an object a record now owns.
                try {
                    const committed = await Promise.all(keys.map((key) => repository.exists({ filter: { key, disk: options.disk } })));
                    keys = keys.filter((_key, index) => !committed[index]);
                }
                catch (verificationError) {
                    throw new FileRepositoryError('FILE_COMMIT_UNCERTAIN', 'Could not verify database commit; uploaded objects were retained for reconciliation.', { cause: new AggregateError([cause, verificationError]) });
