            const results = await Promise.allSettled(keys.map((key) => this.drive.use(options.disk).delete(key)));
            const failures = results.filter((result) => result.status === 'rejected');
            if (failures.length)
                throw new FileRepositoryError('FILE_CLEANUP_FAILED', 'Upload failed and some objects could not be removed.', {
                    cause: new AggregateError([
                        cause,
                        ...failures.map((result) => result.reason),
                    ]),
                });
            throw cause;
        };
        const operations = {
            validateCollection,
            getUrl,
            getStorageUrl: async (record) => {
                const disk = this.drive.use(record.disk);
                try {
                    const url = (await disk.getVisibility(record.key)) === 'public'
                        ? await disk.getUrl(record.key)
